INSERT INTO `anniversarius_arda18` (`id`, `title`, `fname`, `position`, `org_name`, `bless`) VALUES
(42, 'นาย', 'กิตติชัย รักษาทรัพ์', 'นักวิเคราะห์สารสนเทศ', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)', 'ขอให้ก้าวหน้า มั่นคง เพื่อพัฒนางานวิจัยด้านการเษตรต่อไป'),
(3, 'นางสาว', 'นฤมล เข็มกลัดเงิน', 'อาจารย์ ดร.', 'มหาวิทยาลัยแม่โจ้', 'ยินดีกับ สวก. ด้วยค่ะ ขอให้เป็นแหล่งทุนที่สร้างประโยชน์ให้แก่ประเทศและประชาชนแบบนี้ต่อไปเรื่อยๆค่ะ '),
(4, 'ดร.', 'วราภรณ์ แสงทอง', 'อาจารย์', 'มหาวิทยาลัยแม่โจ้', 'ขอให้ สวก อยู่คู่นักวิจัยไทยตลอดไปค่ะ'),
(5, 'นางสาว', 'ศิริรัตน์ เร่งพิพัฒน์', 'ศาสตราจารย์ ดร', 'จุฬาลงกรณ์มหาวิทยาลัย', 'ทีมสวก แข็งแรง มีความสุข สนุกกับงาน  พร้อมก้าวต่อไปเพื่อสร้างผลงานทางด้านเกษตรไทยให้ยั่งยืน '),
(6, 'นางสาว', 'อุมารินทร์ โฉมเฉิด', 'นักวิเคราะห์อาวุโส 2', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ', 'ขอแสดงความยินดีด้วยค่ะ '),
(7, 'นางสาว', 'ภรภัค พชรพลอย', 'ผู้ตรวจสอบภายในอาวุโส1', 'หน่วยตรวจสอบภายใน', 'ขอให้ สวก. มีงานวิจัยใหม่ๆ เพื่อพัฒนาและนำพาเกษตรไทยให้ก้าวไกลตลอดไป'),
(8, 'นาง', 'ปิยนุช นาคะ', 'ที่ปรึกษาสำนักงาน สวก.', 'สวก.', 'ขออวยพรให้ สวก เป็นผู้นำการวิจัย และพัฒนาด้านการเกษตร เทคโนโลยี บุคลากรด้านการเกษตร อย่างครบวงจร ของประเทศ และเป็นที่รู้จักทั้งในและต่างประเทศ บรรลุเป้าหมาย อย่างยั่งยืน'),
(9, 'ดร.', 'กำลัง ชุมพลบัญชร', 'ผู้ช่วยอธิการบดีฝ่ายวิทยาเขตกาญจนบุรี', 'มหาวิทยาลัยมหิดล', 'ขอแสดงความยินดีกับ สวก.เนื่องในโอกาสวันคล้ายวันสถาปนา ขอให้ สวก.เป็นกำลังสำคัญในการพัฒนาประเทศด้วยการสนับสนุนงานวิจัยและนวัตกรรมตลอดไป'),
(10, 'นางสาว', 'รุ่งนภา แซ่เอ็ง', 'รศ.', 'มหาวิทยาลัยบูรพา', 'ขอแสดงความยินดีกับ สวก.หน่วยงานที่สนับสนุนและดูแลนักวิจัยด้านการเกษตร ในวันครบรอบ 18 ปีค่ะ'),
(11, 'นางสาว', 'พนิดา เล้าชาญวุฒิ', 'อาจารย์ ', 'มหาวิทมหาสารคาม', 'Happy 18th Anniversary Day  to ARDA นะคะ\r\n\r\nขอให้ สวก. เป็นองค์กรแห่งคุณธรรมที่อยู่เคียงคู่กับการเกษตรของไทยตลอดไปนะคะ'),
(12, 'other', 'กรณ์กนก อายุสุข', 'อาจารย์/รองคณบดีฝ่ายบริหาร', 'คณะทรัพยากรชีวภาพและเทคโนโลยี, มจธ.', 'สวก. ถือเป็นหน่วยงานบริหารจัดการทุนที่มีประสิทธิภาพสูงสุด เป็นกำลังหลักของประเทศ เนื่องในโอกาสวันคล้ายวันสถาปนา สวก. ครบรอบ 18 ปี ขอคุณความดีทั้งหลายปกป้องคุ้มครองให้บุคคลากรของ สวก. ทุกระดับและผู้มีส่วนเกี่ยวข้องกับ สวก. ทุกท่าน มีความสุข มีความสำเร็จ มีเงิน มีสุขภาพแข็งแรง และเป็นกำลังผลักดันให้ สวก. เป็นหน่วยงานที่มีความเจริญรุดหน้ายิ่งๆ ขึ้นไป'),
(13, 'นาย', 'สีวบูรณ์ สิรีรัฐวงศ์', 'รองศาสตราจารย์', 'คณะแพทยศาสตร์ มหาวิทยาลัยเชียงใหม่', 'ขอให้เป็นหน่วยงานที่ช่วยเสริมสร้างความเข้มแข็งและพัฒนาประเทศตลอดไปครับ'),
(14, 'นาย', 'ณฐุปกรน์ เดชสุภา', 'ผู้ช่วยศาตราจารย์ ดร.', 'ภาควิชารังสีเทคนิค คณะเทคนิคการแพทย์ มหาวิทยลัยเชียงใหม่', 'ขอให้ สวก. ดำเนินกิจการด้วยคุณภาพและประสบความสำเร็จยิ่งๆขึ้นไป'),
(15, 'นาย', 'ณัฐพิสิษฐ์ จารุพงศ์', 'นักวิชาการเผยแพร่ปฏิบัติการ', 'กรมส่งเสริมการเกษตร', 'เนื่องในโอกาสวันคล้ายวันสถาปนา ครบรอบปีที่ 18 ของ สวก. ก็อยากให้ผลิตผลงานวิจัยดีๆ ออกมาสู่สาธารณะ สร้างความเป็นที่รู้จักมากขึ้นไปอีก เพื่อให้ประชาชนทั่วไปเกิดความสนใจและเกิดทัศคติที่ว่า \"วิจัยเกษตร คิดถึง สวก.\"'),
(16, 'นางสาว', 'สิรินดา นัดสูงวงศ์', 'เจ้าหน้าที่สนับสนุนงานวิเทศสัมพันธ์', 'สวก.', 'ร่ำรวย มีความสุขกันทุกคนน'),
(17, 'นางสาว', 'จิราภรณ์ ริมประชา', 'นักวิเคราะห์อาวุโส 1', 'สวก.', 'เนื่องด้วยวันคล้ายวันสถาปนา ขอให้ สวก. เป็นองค์การชั่นนำดานการวิจัยการเกษตร มั่นคง แข็งแรง ตลอดไป'),
(18, 'นาย', 'คุณากร เนตรสืบสาย', 'นักวิเคราะห์ปฏิบัติการ 1', 'สวก.', 'ขอให้ก้าวหน้า มั่นคง เพื่อพัฒนางานวิจัยด้านการเษตรต่อไป'),
(19, 'นางสาว', 'สุภัทตรา  นุชนารถ', 'Soil Chemist', 'Royal Irrigation Department', 'ขอแสดงความยินดี ขอให้มีกำลังส่งเสริมนักวิจัยในการพัฒนาชาติไปอีกนาน'),
(20, 'นาย', 'ทิวธ​วัฒ​ นา​พิรุณ​', 'อาจารย์​', 'ภาควิชา​เทคโนโลยี​ชีวภาพ​ คณะ​วิทยา​ศาสตร์​และ​เทคโนโลยี​ มหา​วิทยาลัย​ธรรมศาสตร์​', 'ขอแสดงความยินดี​ เนื่องในวันคล้ายวันสถาปนา​ สวก.ครับ'),
(21, 'นาย', 'สรวิศ ธานีโต', 'อธิบดีกรมปศุสัตว์', 'กรมปศุสัตว์', 'ครบรอบ 18 ปี วันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ขออาราธนาคุณพระศรีรัตนตรัย จงดลบันดาลให้บุคลากรสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) มีแต่ความสุขกายสบายใจ ปราศจากโรคภัยต่างๆ'),
(22, 'นาย', 'วุฒิพล จันทร์สระคู', 'ผู้อำนวยการศูนย์', 'ศูนย์วิจัยเกษตรวิศวกรรมสุราษฎร์ธานี', 'ขอแสดงความยินดีกับ สวก เนื่องในโอกาสวันคล้ายวันสถาปนาฯ และขอให้องค์กรประสบความสำเร็จและพัฒนายิ่งๆขึ้นไปนะครับ'),
(23, 'นาย', 'ฤทธิชัย อัศวราชันย์ ', 'ผู้ช่วยศาสตราจารย์ ', 'มหาวิทยาลัยแม่โจ้', 'ขอเปลี่ยนคำอวยพร เป็นคำขอบคุณมากกว่า แทนคำขอบคุณจากเกษตรกรในพื้นที่โครงการสะโงะ ที่สนับสนุนวิจัยจนพัฒนาเครื่องอบแห้ง ที่ช่วยตอบโจทย์ให้เกษตรกร มีรายได้จากการปลูกดอกคาโมมายล์ (เพิ่มจาก 50 เป็น 70) และเก๊กฮวยเหลือง (เพิ่มจาก 20 เป็น 47) จนกลายเป็นอาชีพหลักให้เกษตรกรในพื้นที่มีรายได้เพียงพอต่อการดำรงค์ชีพ ไม่ต้องโยกย้ายแรงงานไปอยู่ต่างถิ่น ในนามนักวิจัย มหาวิทยาลัยแม่โจ้ได้มีโอกาสพัฒนาเครื่องจักรแปรรูปแข่งขันกับเครื่องจักรจากต่างประเทศ และถูกนำไปใช้ได้จริง ขอบคุณแทนเกษตรกร 250 ครอบครัวด้วยครับ'),
(24, 'นาย', 'เฉลิมพงษ์ แสนจุ้ม', 'ผู้ช่วยคณบดี', 'คณะเภสัชศาสตร์ มหาวิทยาลัยเชียงใหม่', 'ขอให้ สวก. ร่วมเป็นส่วนหนึ่งในการขับเคลื่อนงานวิจัยและพัฒนาด้านการเกษตร ที่ตอบสนองต่อเศรษฐกิจญานรากและเศรษฐกิจของประเทศต่อไปอย่างยั่งยืนครับ'),
(25, 'นางสาว', 'ปกิตตา จงอักษร', 'เกษตรกร/นิสิตทุนสวก.', 'ปกิตตาออร์แกนิคฟาร์ม', 'ขอขอบคุณที่ช่วยพัฒนาวิจัยการเกษตรของไทย ขอให้เจ้าหน้าที่ทุกท่านมีกำลังที่จะพัฒนาประเทศชาติ มีกำลังใจที่เปี่ยมล้นในการทำงาน สุขภาพร่างกายแข็งแรง ข้าพเจ้านางสาว ปกิตตา จงอักษร ขอสัญญาว่าจะตั้งใจนำความรู้ที่ได้จากการเรียนทุนสวก. พัฒนาชุมชนและประเทศชาติอย่างเต็มความสามารถ...ฉันรัก สวก.'),
(26, 'นางสาว', 'บุษกร ก้อนทอง', 'นักวิเคราะห์ปฏิบัติการ 1', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)', 'ขอให้มีงบประมาณเยอะๆ เป็นหน่วยงานที่น่ารัก ใครก็อยากมาร่วมงานด้วย ขอให้มีพลังบวก แฮปปี้ๆกันทั้งสวก. นะค้า '),
(27, 'นางสาว', 'บุญนภา จันทรกุล', 'นักวิเคราะห์ปฏิบัติการ 2', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)', 'ขอให้ สวก. มีชื่อเสียง และเป็นผู้นำด้านการให้ทุนการเกษตรยิ่งๆขึ้น และขอให้ผู้บริหาร และเจ้าหน้าที่ทุกคนพบเจอแต่เรื่องราวดีดี ปราศจากอุปสรรคใดทังการดำเนินชีวิตและหน้าที่การงานค่ะ'),
(28, 'นาย', 'ณกรณ์ ตรรกวิรพัท', 'ผู้ว่าการการยางแห่งประเทศไทย', 'การยางแห่งประเทศไทย', 'ในโอกาสนี้ ขออาราธนาอำนาจแห่งคุณพระศรีรัตนตรัยและสิ่งศักดิ์สิทธิ์ทั้งหลาย ที่ทุกท่านให้ความเคารพนับถือ โปรดดลบันดาลให้คณะผู้บริหาร และผู้ที่มีส่วนเกี่ยวข้องทุกท่าน จงประสบแต่ความสุข ความเจริญ'),
(29, 'นาย', 'ณกรณ์ ตรรกวิรพัท', 'ผู้ว่าการการยางแห่งประเทศไทย', 'การยางแห่งประเทศไทย', 'ในโอกาสนี้ ขออาราธนาอำนาจแห่งคุณพระศรีรัตนตรัยและสิ่งศักดิ์สิทธิ์ทั้งหลาย ที่ทุกท่านให้ความเคารพนับถือ โปรดดลบันดาลให้คณะผู้บริหาร และผู้ที่มีส่วนเกี่ยวข้องทุกท่าน จงประสบแต่ความสุข ความเจริญ'),
(30, 'นาย', 'ทศพร ศรีศักดิ์', 'นายกสมาคมอนุรักษ์และพัฒนาควายไทย', 'สมาคมอนุรักษ์และพัฒนาควายไทย', 'ขอแสดงความยินดีในโอกาสครบรอบ 18 ปี ขอให้หน่วยงาน สวก.มีความเจริญรุ่งเรือง สร้างสรรงานวิจัยและนวัตกรรมที่ดีเพื่อพี่น้องเกษตรกรและประเทศชาติตลอดไป'),
(31, 'นาย', 'กัมปนาท สมปานวัง', 'นักวิเคราะห์สารสนเทศอาวุโส 2', 'สท', 'สวก. สร้างงานวิจัยดีๆ ให้แก่ประเทศชาติ และคงอยู่คู่กับประเทศตลอดไป'),
(32, 'นาย', 'พัชโรภาส เหลืองวิไล', 'ผู้อำนวยการสำนักเทคโนโลยีสาระสนเทศ', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)', 'ขออวยพรให้การดำเนินงานของ สวก. ประสบผลสำเร็จตามเจตจำนงทุกประการ'),
(33, 'นาย', 'สีวบูรณ์ สิรีรัฐวงศ์', 'รองศาสตราจารย์', 'คณะแพทยศาสตร์ มหาวิทยาลัยเชียงใหม่', 'ขอให้เป็นหน่วยงานที่ช่วยเสริมสร้างความเข้มแข็งและพัฒนาประเทศตลอดไปครับ'),
(34, 'นาง', 'สุภาวดี พาหิระ', 'อาจารย์', 'คณะเภสัชศาสตร์ มหาวิทยาลัยนเรศวร', 'ยินดีกับการครบรอบวันสถาปนา ขอให้ สวก เป็นหน่วยงานที่เป็นที่พึ่งให้ชุมชน ในการขับเคลื่อนงานวิจัยทางการเกษตร ประเทศไทย ตลอดไปค่ะ'),
(35, 'นาย', 'นายศักดิ์นันท์ ไชยพันธ์', 'เกษตรกรไทย', 'บ้านไทยวัฒนา ต.นากระแซงอ.เดชอุดม จ.อุบล', 'ขอคุณพระรัตนตรัยจงปกป้องคุ้มครองรักษาให้ สวก\r\nจงมีแต่ความเจริญก้าวหน้า และดูแลเกษตรกรต่อไปนานๆ'),
(36, 'เป็นเกษตรกร', 'นายศักดิ์นันท์ ไชยพันธ์', 'เกษตรกรไทย', 'บ้านไทยวัฒนา ต.นากระแซงอ.เดชอุดม จ.อุบล', 'ขอคุณพระรัตนตรัยจงปกป้องคุ้มครองรักษาให้ สวก\r\nจงมีแต่ความเจริญก้าวหน้า และดูแลเกษตรกรต่อไปนานๆ'),
(37, 'นาย', 'ศิริพัฒน์ มีทับทิม', 'CEO', 'บอร์น อาร์ดีไอ เซ็นเตอร์', 'ขอแสดงความยินดีกับก้าวที่ 18 ของ สวก. ขอให้ สวก. เป็นผู้นำในด้านการส่งเสริมการวิจัยและพัฒนาการเกษตรเพื่อให้เกษตรไทยเป็นเสาหลักให้แก่ชาวไทยตลอดไป ขอแสดงความยินดีเป็นอย่างยิ่ง'),
(38, 'นางสาว', 'นางสาวอัญชรี ธงไชย', 'คนธรรมดา', 'ทำงานบริษัทโกลสวอลพาสติกค่ะ', 'คือในครอบครัวยังไม่มีใครได้รับเงิน15000เลยค่ะเพราะอยุ่คนล่ะที่ค่ะต่างคนต่างไม่รุ้ว่าทำยังไงค่ะ..แต่ตอนนี้อยากรับสิทธิ์นั้นเพราะตอนนี้หนูมาอยู่กับพ่อแม่และน้องสาวแล้วค่ะ'),
(39, 'นางสาว', 'นางสาวอัญชรี ธงไชย', 'คนธรรมดา', 'ทำงานบริษัทโกลสวอลพาสติกค่ะ', 'คือในครอบครัวยังไม่มีใครได้รับเงิน15000เลยค่ะเพราะอยุ่คนล่ะที่ค่ะต่างคนต่างไม่รุ้ว่าทำยังไงค่ะ..แต่ตอนนี้อยากรับสิทธิ์นั้นเพราะตอนนี้หนูมาอยู่กับพ่อแม่และน้องสาวแล้วค่ะ'),
(40, 'นาง', 'รดา รุจิณรงค์', 'ผู้เชี่ยวชาญด้านเทคโนโลยีและระบบสารสนเทศ', 'กรมชลประทาน', 'ขอแสดงความยินดีในวาระที่ครบ 18 ปีกับ สวก.'),
(41, 'นางสาว', 'นงพงา แสงเจริญ', 'นักวิเคราะห์ปฏิบัติการ 2', 'สำนักงานพัฒนาาารวิจัยการเกษตร', 'ขอแสดงความยินดีกับสำนักงานพัฒนาการวิจัยการเกษตร ในวาระครบรอบ 18 ปี ผลงานวิจัยที่ สวก.สร้างสรรค์จะนำมาซึ่งประโยชน์แก่ประเทศชาติสืบต่อไป'),
(43, 'นางสาว', 'นิศากร วรวุฒิยานันท์', 'นีกวิเครอาวุโส1', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์กรมหาชน)', 'ขอให้ สวก. เจริญก้าวหน้าตลอดไป'),
(44, 'นางสาว', 'คณิศรา ธัญสุนทรสกุล', 'รองอธิการบดี', 'มหาวิทยาลัยราชภัฏอุดรธานี / ศูนย์  AIC', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร  (องค์การมหาชน) ครบรอบ 18 ปี เป็นองค์กรที่ส่งเสริมและพัฒนางานวิจัยสร้างองค์ความรู้ที่มีคุณค่าและสร้างมูลค่าทางเศรษฐกิจให้กับประเทศ และชุมชนท้องถิ่น'),
(45, 'นางสาว', 'นงเยาว์', 'เอียดราช', 'สวก.', 'ขอให้ สวก.เจริญรุ่งเรือง ก้าวหน้า พัฒนางานวิจัยแก่ประเทศและเกษตรกรต่อไป'),
(46, 'นาย', 'ต่อลาภ', 'เลขานุการ', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)', 'ขอแสดงความยินดีกับ สวก. ด้วยครับ'),
(47, 'นาย', 'นพวุฒิ พงษ์บุญ', 'เจ้าหน้าที่สนับสนุนนักวิเคราะห์', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)', 'ขอแสดงความยินดีในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)'),
(48, 'นางสาว', 'นริศรา ', 'เจ้าหน้าที่สนับสนุน (นักวิเคราะห์)', 'สวก.', 'ขอให้เป็นหน่วยงานที่ช่วยส่งเสริม สนับสนุน และพัฒนางานวิจัยการเกษตร ที่ประสบความสำเร็จตลอดไป'),
(49, 'รองศาสตราจารย์ ดร.', 'ชยาพร วัฒนศิริ', 'อธิการบดีมหาวิทยาลัยแม่ฟ้าหลวง', 'มหาวิทยาลัยแม่ฟ้าหลวง', 'ในนามมหาวิทยาลัยแม่ฟ้าหลวง ดิฉันขอแสดงความยินดีต่อสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) (สวก.) เนื่องในโอกาสครบรอบ \"วันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี\" ในวันที่ 15 มีนาคมคม 2564\r\n\r\nมหาวิทยาลัยแม่ฟ้าหลวงและสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) มีความสัมพันธ์อันดีมาอย่างยาวนาน ในโอกาสนี้ดิฉันจึงขอแสดงความยินดีกับท่านอีกครั้งหนึ่งและหวังเป็นอย่างยิ่งว่าทั้งสองสถาบันเราจะร่วมมือในการศึกษา วิจัย และพัฒนาองค์ความรู้ไปสู่การสร้างสรรค์ผลงานวัตกรรมเพื่อพัฒนาประเทศสืบต่อไป'),
(50, 'นางสาว', 'ปิยาภัสร์ ปิยะจารุวัฒน์', 'เจ้าหน้าที่สนับสนุน สส', 'สส', 'สุขสันต์วันเกิดครบรอบ 18 ปี'),
(51, 'รองศาสตราจารย์', 'สุนทร สุทธิบาก', 'ผู้อำนวยการศูนย์เทคโนโลยีเกษตรและนวัตกรรม (AIC) จังหวัดอุดรธานี', 'มหาวิทยาลัยราชภัฏอุดรธานี', 'เนื่องในโอกาสครบรอบ 18 ปี ของสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ศูนย์เทคโนโลยีเกษตรและนวัตกรรม (AIC) จังหวัดอุดรธานี ขอแสดงความยินดีและชื่นชมในการทำหน้าที่เป็นหน่วยงานที่ช่วยส่งเสริม สนับสนุนและพัฒนาการวิจัยการเกษตรให้กับกลุ่มเกษตรกร ในโอกาสนี้ศูนย์ AIC จังหวัดอุดรธานี ขอแสดงความปราถนาดีมายังคณะผู้บริหารและบุคลากรของสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ทุกท่านประสบความสุข ความเจริญ และประสบความสำเร็จยิ่งๆ ขึ้นไป'),
(52, 'ผู้ช่วยศาสตราจารย์ ดร.', 'นิวัติ แก้วประดับ', 'อธิการบดี', 'มหาวิทยาลัยสงขลานครินทร์', 'เนื่องในโอกาสครบรอบ 18 ปี แห่งการสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ในวันที่ 15 มีนาคม พ.ศ.2564 นี้ ผมมีความยินดีเป็นอย่างยิ่งที่ได้เห็นความเจริญก้าวหน้าอย่างต่อเนื่องมั่นคง และความสําเร็จของสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ที่จะส่งผลให้การเกษตรของไทยได้รับการส่งเสริม สนับสนุน และพัฒนาทั้งด้านงานวิจัย ด้านบุคลากร ด้านข้อมูลและสารสนเทศ รวมทั้งด้านความร่วมมือทางวิชาการกับสถาบันการศึกษาหรือสถาบันอื่นของรัฐและเอกชนเพื่อผลิตและพัฒนางานวิจัยและนักวิจัยการเกษตรทั้งในประเทศและในระดับสากล\r\n\r\nมหาวิทยาลัยสงขลานครินทร์ ซึ่งเป็นสถาบันอุดมศึกษาที่เป็นกลไกหลักในการพัฒนาภาคใต้และประเทศไทย ได้มีแนวทางการดำเนินงานทางวิชาการที่สอดคล้องกับนโยบายในการขับเคลื่อนให้มีการพัฒนาด้านการเกษตร โดยใช้องค์ความรู้ที่ได้จากการวิจัย ร่วมกับการนำนวัตกรรมและเทคโนโลยีมาใช้พัฒนาสู่การเกษตรอัจฉริยะในอนาคต โดยมีความร่วมมือในด้านวิชาการ การวิจัย และบริการวิชาการกับหน่วยงานในสังกัดกระทรวงเกษตรและสหกรณ์ รวมทั้งสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) มาอย่างต่อเนื่องโดยเฉพาะที่เกี่ยวข้องกับพื้นที่ภาคใต้ เช่นพืชเศรษฐกิจ ยางพารา ปาล์มน้ำมัน และการเพาะเลี้ยงสัตว์น้ำ เป็นต้น\r\n\r\nในนามของผู้บริหาร คณาจารย์ บุคลากร นักศึกษา และศิษย์เก่ามหาวิทยาลัยสงขลานครินทร์ ผมหวังเป็นอย่างยิ่งว่าทั้ง 2 สถาบันจะได้กระชับความร่วมมือให้ใกล้ชิดกันมากยิ่งขึ้นในอนาคต เพื่อเพิ่มประสิทธิภาพและพัฒนาการจัดการความรู้  งานวิจัย และนวัตกรรมด้านเกษตรของประเทศไทยให้ยั่งยืน และนำไปสู่การพัฒนาคุณภาพชีวิตของเกษตรกรและเศรษฐกิจของประเทศต่อไป\r\n'),
(53, 'ผู้ช่วยศาสตราจารย์ ดร.', 'นิวัติ แก้วประดับ', 'อธิการบดี', 'มหาวิทยาลัยสงขลานครินทร์', 'เนื่องในโอกาสครบรอบ 18 ปี แห่งการสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ในวันที่ 15 มีนาคม พ.ศ.2564 นี้ ผมมีความยินดีเป็นอย่างยิ่งที่ได้เห็นความเจริญก้าวหน้าอย่างต่อเนื่องมั่นคง และความสําเร็จของสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ที่จะส่งผลให้การเกษตรของไทยได้รับการส่งเสริม สนับสนุน และพัฒนาทั้งด้านงานวิจัย ด้านบุคลากร ด้านข้อมูลและสารสนเทศ รวมทั้งด้านความร่วมมือทางวิชาการกับสถาบันการศึกษาหรือสถาบันอื่นของรัฐและเอกชนเพื่อผลิตและพัฒนางานวิจัยและนักวิจัยการเกษตรทั้งในประเทศและในระดับสากล\r\n\r\nมหาวิทยาลัยสงขลานครินทร์ ซึ่งเป็นสถาบันอุดมศึกษาที่เป็นกลไกหลักในการพัฒนาภาคใต้และประเทศไทย ได้มีแนวทางการดำเนินงานทางวิชาการที่สอดคล้องกับนโยบายในการขับเคลื่อนให้มีการพัฒนาด้านการเกษตร โดยใช้องค์ความรู้ที่ได้จากการวิจัย ร่วมกับการนำนวัตกรรมและเทคโนโลยีมาใช้พัฒนาสู่การเกษตรอัจฉริยะในอนาคต โดยมีความร่วมมือในด้านวิชาการ การวิจัย และบริการวิชาการกับหน่วยงานในสังกัดกระทรวงเกษตรและสหกรณ์ รวมทั้งสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) มาอย่างต่อเนื่องโดยเฉพาะที่เกี่ยวข้องกับพื้นที่ภาคใต้ เช่นพืชเศรษฐกิจ ยางพารา ปาล์มน้ำมัน และการเพาะเลี้ยงสัตว์น้ำ เป็นต้น\r\n\r\nในนามของผู้บริหาร คณาจารย์ บุคลากร นักศึกษา และศิษย์เก่ามหาวิทยาลัยสงขลานครินทร์ ผมหวังเป็นอย่างยิ่งว่าทั้ง 2 สถาบันจะได้กระชับความร่วมมือให้ใกล้ชิดกันมากยิ่งขึ้นในอนาคต เพื่อเพิ่มประสิทธิภาพและพัฒนาการจัดการความรู้  งานวิจัย และนวัตกรรมด้านเกษตรของประเทศไทยให้ยั่งยืน และนำไปสู่การพัฒนาคุณภาพชีวิตของเกษตรกรและเศรษฐกิจของประเทศต่อไป\r\n\r\n'),
(54, 'นาย', 'ฉันทานนท์ วรรณเขจร', 'เลขาธิการ', 'สำนักงานเศรษฐกิจการเกษตร', 'ขอแสดงความยินดี เนื่องในวันคล้ายวันสถาปนา ส.ว.ก.ครบรอบ 18 ปี'),
(55, 'นาย', 'ประพิศ  จันทร์มา', 'อธิบดีกรมชลประทาน', 'กรมชลประทาน  กระทรวงเกษตรและสหกรณ์', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(56, 'นาย', 'วิศิษฐ์ ศรีสุวรรณ์', 'อธิบดีกรมส่งเสริมสหกรณ์', 'กรมส่งเสริมสหกรณ์', 'กรมส่งเสริมสหกรณ์ขอแสดงความยินดี เนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนางานวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(57, 'นาย', 'ปราโมทย์ ยาใจ', 'อธิบดี', 'กรมหม่อนไหม', 'ขอแสดงความยินดีด้วยครับ'),
(58, 'นาย', 'วิศิษฐ์ ศรีสุวรรณ์', 'อธิบดีกรมส่งเสริมสหกรณ์', 'กรมส่งเสริมสหกรณ์', 'กรมส่งเสริมสหกรณ์ขอแสดงความยินดี เนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนางานวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(59, 'นางสาว', 'เกษรา อินทร์ศิริ', 'นักวิเคราะห์อาวุโส 2', 'สำนักพัฒนาบุคลากรวิจัย', 'ขอให้ สวก. เป็นที่รู้จัก และอยู่กับภาคการเกษตรไปนานๆนะคะ ภูมิใจที่ได้เป็นส่วนหนึ่งของ สวก.คะ'),
(60, 'นางสาว', 'จิราภรณ์ ริมประชา', 'นักวิเคราะห์อาวุโธ1', 'สำนักพัฒนาบุคลากรวิจัย', 'ขอให้มั่นคง แข็งแรง ๆๆ'),
(61, 'นางสาว', 'พรวิมล วงค์หาญ', 'เจ้าหน้าที่สนับสนุน', 'สพบ', 'ขอแสดงความยินดีเนื่องในโอกาสครบรอบ 18 ปี วันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ด้วยค่ะ'),
(62, 'นาย', 'ปณิธาน มีไชยโย', 'รองผู้อำนวยการ อ.ต.ก. รักษาการแทนในตำแหน่งผู้อำนวยการ อ.ต.ก. ', 'องค์การตลาดเพื่อเกษตรกร (อ.ต.ก.)', 'ขอแสดงความยินดีกับ สำนักงานพัฒนาการวิจัยการเกษตร ในวาระครบรอบ 18 ปี ขอให้สวก. ส่งเสริม สนับสนุนและพัฒนาการวิจัยการเกษตร เพื่อสร้างความเข้มแข็งของภาคการเกษตรไทยให้ยั่งยืนสืบต่อไป '),
(63, 'นางสาว', 'สุนิสา เอกธิการ', 'ผู้อำนวยการกองประสานงานโครงการพระราชดำริและโครงการพิเศษ', 'สำนักงานการปฏิรูปที่ิดินเพื่อเกษตรกรรม (ส.ป.ก.)', 'ขอแสดงความยินดีเนื่องในวันคล้ายวันสถาปนาสำนักงานวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี\r\n'),
(64, 'นาย', 'รศ.ดร.ฤกษ์ชัย ฟูประทีปศิริ', 'รักษาราชการแทนอธิการบดีมหาวิทยาลัยเทคโนโลยีราชมงคลตะวันออก', 'มหาวิทยาลัยเทคโนโลยีราชมงคลตะวันออก', 'ขอแสดงความยินดีในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) 15 มีนาคม 2564'),
(65, 'นางสาว', 'ประวีณา อินทร์ยิ้ม', 'ผอ.สำนักพัฒนาบุคลากรวิจัย', 'สำนักงานพัฒนาการวิจัยการเกษตร(องค์การมหาชน)​', 'ยินดีกับ สวก. เติบโต ก้าวหน้า เป็นผู้ชี้ทิศทางวิจัยการเกษตรของประเทศไทยต่อไปค่ะ'),
(66, 'นาย', 'วุฒิชัย จั่นเพ็ชร', 'หัวหน้าฝ่ายวิจัยและพัฒนาการเลี้ยงโคนม', 'องค์การส่งเสริมกิจการโคนมแห่งประเทศไทย (อ.ส.ค.)', 'ในนามองค์การส่งเสริมกิจการโคนมแห่งประเทศไทย (อ.ส.ค.) ขอร่วมแสดงความยินดีเนื่องในโอกาส วันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร(องค์การมหาชน)ครบรอบ 18 ปี ในการนี้ขออำนาจพระศรีรัตนตรัยโปรดบัลดาลให้เจ้าหน้าที่ทุกท่านประสพความสุขความเจริญ พร้อมทั้งมีกำลังกาย กำลังใจ สติปัญญา เพื่อพัฒนางานวิจัยเพื่อการเกษตร สืบไป'),
(67, 'นาย', 'มีศักดิ์  ภักดีคง', 'อธิบดี', 'กรมประมง', 'กระผมขอแสดงความยินดีในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ปีที่ 18 ในวันที่ 15 มีนาคม 2564 ด้วยครับ'),
(68, 'ผู้ช่วยศาสตราจารย ดร.', 'พิทักษ์ จันทร์เจริญ', 'รองอธิการบดีฝ่ายบริหาร', 'มหาวิทยาลัยสวนดุสิต', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(69, 'นาย', 'ศาสตราจารย์คลินิก นายแพทย์นิเวศน์ นันทจิต', 'อธิการบดีมหาวิทยาลัยเชียงใหม่', 'มหาวิทยาลัยเชียงใหม่', 'ในนามคณะผู้บริหาร คณาจารย์ บุคลากร และนักศึกษาของมหาวิทยาลัยเชียงใหม่  ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร และขออาราธนาคุณพระศรีรัตนตรัย พระบรมธาตุดอยสุเทพ ครูบาเจ้าศรีวิไชย สิริวิชโย ได้โปรดดลบันดาลให้ท่านผู้อำนวยการ และบุคลากรในสังกัด ประสบแต่ความสุข ความเจริญ มีสุขภาพพลานามัยแข็งแรง ยิ่ง ๆ ขึ้นไป'),
(70, 'นาย', 'โอภาส  ทองยงค์', 'อธิบดีกรมตรวจบัญชีสหกรณ์', 'กรมตรวจบัญชีสหกรณ์', 'ในโอกาสครบรอบ 8 ปี แห่งการสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) วันที่ 15 มีนาคม 2564 ในนามของกรมตรวจบัญชีสหกรณ์ กระผมขอส่งความปราถนาดีมายังบุคลากรในสังกัดสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)  ตลอดจนผู้ที่เกี่ยวข้องทุกท่าน และขออาราธนาคุณพระศรีรัตนตรัย และสิ่งศักดิ์สิทธิ์ในสากลโลก ได้โปรดอำนวยพรให้บุคลากรของสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ทุกท่าน จงประสบแต่ความสุข ความเจริญ มีกำลังกาย กำลังใจที่เข้มแข็ง และบรรลุความความเสร็จในทุกประการ'),
(71, 'นางสาว', 'สุรีรัตน์. อยู่เกิด', 'ผอ.สำนักบริหาร', 'สวก.', 'สวก. เป็นองค์กรเล็กๆ ที่ทำหน้าที่ผลักดันงานวิจัยสู่การใช้ประโยชน์  ผลิตบุคลากรด้านการวิจัยเพื่อนำไปสู่การพัฒนาประเทศ \r\nขอขอบคุณ จนท. ทุกท่าน ที่ทุ่มเทแรงกายและแรงใจ ตลอดระยะเวลาที่ผ่านมา \r\nและเป็นกำลังใจให้ กับปีต่อๆไป ด้วยค่ะ'),
(72, 'นางสาว', 'อนงค์ จันดำ', 'นักจัดการงานทั่วไปปฏิบัติการ 2', 'สำนักพัฒนาบุคลากรวิจัย', 'เจริญก้าวหน้า มั่งคง โปร่งใส สร้างงานวิจัยที่ช่วยเกษตรกรให้มีรายได้มากขึ้นแบบนี้ไปนานๆ นะคะ'),
(73, 'นาย', 'วิณะโรจน์  ทรัพย์ส่งสุข', 'เลขาธิการ ส.ป.ก.', 'สำนักงานการปฏิรูปที่ดินเพื่อเกษตรกรรม', 'ขอแสดงความยินดีเนื่องในโอกาส \"วันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร(องค์การมหาชน) ครบรอบ 18 ปี\"\r\nขอให้อยู่คู่เกษตรกรไทยตลอดไป'),
(74, 'นาย', 'พิเชษฐ์  วิริยะพาหะ', 'อธิบดีกรมวิชาการเกษตร', 'กรมวิชาการเกษตร', 'ขอร่วมแสดงความยินดี เนื่องในวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ ๑๘ ปี '),
(75, ' ผู้ช่วยศาสตราจารย์', 'ชัยชาญ  ถาวรเวช', 'อธิการบดี', 'มหาวิทยาลัยศิลปากร', 'มหาวิทยาลัยศิลปากรขออาราธนาอำนาจคุณพระศรีรัตนตรัยและสิ่งศักดิ์สิทธิ์โปรดอำนวยพรให้ท่าน ผู้บริหาร และบุคลากรของสำนักงานพัฒนาการวิจัยการเกษตร จงประสบแต่ความสุขสวัสดิ์พิพัฒนมงคลสัมฤทธิผลเจริญด้วยจตุรพิธพรชัยทุกประการ'),
(76, 'รองศาสตราจารย์', 'จิระพันธ์  ห้วยแสน', 'อธิการบดีมหาวิทยาลัยกาฬสินธุ์', 'มหาวิยาลัยกาฬสินธุ์', 'ในนามมหาวิทยาลัยกาฬสินธุ์ ขอแสดงความยินดีกับสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) หรือ ARDA เนื่องในโอกาสวันคล้ายวันสถาปนา กระผมขอให้ ARDA มีความเจริญก้าวหน้ายิ่งๆ ขึ้นไป และขอให้บุคลากรของ ARDA ทุกท่านประสบแต่ความสุขความเจริญและมีสุขภาพพลานามัยที่แข็งแรง'),
(77, 'ผู้ช่วยศาสตราจารย์ ', 'ผู้ช่วยศาสตราจารย์ ดร.ธนวรรธน์  พลวิชัย', 'อธิการบดี', 'มหาวิทยาลัยหอการค้าไทย', 'ในโอกาสอันเป็นมงคลนี้กระผมในนามของคณะผู้บริหาร คณาจารย์ เจ้าหน้าที่และนักศึกษามหาวิทยาลัยหอการค้าไทย ขอส่งความปรารถนาดีและขอบารมีแห่งสิ่งศักดิ์สิทธิ์ที่ท่านเคารพนับถือได้โปรดอำนวยพรให้ท่าน คณะผู้บริหาร และเจ้าหน้าที่ของสำนักงานพัฒนาการวิจัยการเกษตร ARDA จงประสบแต่ความสุขสวัสดิ์ มีความเจริญก้าวหน้าในสิ่งที่ดีที่พึงปรารถนาทุกประการ'),
(78, 'นางสาว', 'บณฤทธิ์  บุญ-หลง', 'นักทรัพยากรบุคคลปฏิบัติการ 2', 'สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)', 'ขอแสดงความยินดีในโอกาส สวก. ครบรอบ 18 ปี ค่ะ'),
(79, 'นาย', 'ทองเปลว กองจันทร์ ', 'ปลัดกระทรวง', 'กระทรวงเกษตรและสหกรณ์ ', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนาฯ ครบรอบ 18 ปี และขอส่งความปรารถนาดีมายังผู้บริหารและเจ้าหน้าที่ทุกท่าน ขอให้มีสุขภาพพลานามัยที่สมบูรณ์ แข็งแรง ประกอบกิจการงานได้สำเร็จลุล่วงตามภารกิจ ประสบแต่ความสุข และความเจริญก้าวหน้าสืบไป'),
(80, 'นาย', 'นายอาชว์ชัยชาญ  เลี้ยงประยูร', 'อธิบดีกรมการข้าว', 'กรมการข้าว', 'เนื่องในโอกาสวันคล้ายวันสาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบปีที่ 18 กรมการข้าวขอร่วมแสดงความยินดี และขอให้บุคลลากรจงมีแต่ความสุข เจริญรุ่งเรื่องต่อไป'),
(81, 'นาย', 'พิศาล พงศาพิชณ์', 'เลขาธิการสำนักงานมาตรฐานสินค้าเกษตรและอาหารแห่งชาติ', 'สำนักงานมาตรฐานสินค้าเกษตรและอาหารแห่งชาติ', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร ครบรอบ 18 ปี ครับ'),
(82, 'นาย', 'สุรสีห์ กิตติมณฑล', 'อธิบดีกรมฝนหลวงและการบินเกษตร', 'กรมฝนหลวงและการบินเกษตร', 'ขอแสดงความยินดีในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(83, 'สุคนธ์', 'ท้วมมา', 'ระกษาการผชช.ด้านมาตรฐานการรับรองข้าว', 'กรมการข้าว', 'ขอให้มีผลงานวิจัยดีๆที่ใช้ประโยชน์คู่ประเทศไทยไปนานเท่านานค่ะ'),
(84, 'นาย', 'เข้มแข็ง ยุติธรรมดำรง', 'อธิบดีกรมส่งเสริมการเกษตร', 'กรมส่งเสริมการเกษตร', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(85, 'นางสาว', 'รัชนี  แก้วขาว', 'เจ้าหน้าที่บริหารงานทั่วไป', 'สำนักศิลปวัฒนธรรมและพัฒนาชุมชน มหาวิทยาลัยราชภัฏรำไพพรรณี', 'ขอร่วมแสดงความยินดี เนื่องในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(86, 'ดร.', 'รัชนีพร พุคยาภรณ์ พุกกะมาน', 'อธิการบดี', 'มหาวิทยาลัยศรีปทุม', 'เนื่องในโอกาสครบรอบ 18  ปี   แห่งการสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)    วันจันทร์ที่  15  มีนาคม  2564    ในนามของคณะผู้บริหาร  บุคลากร  และนักศึกษามหาวิทยาลัยศรีปทุม ขอแสดงความยินดีและชื่นชมการขับเคลื่อนและนำพาองค์กรไปได้อย่างทันสมัยมีคุณภาพ  และมีประสิทธิผล ทั้งด้านการบริหาร การวิจัยการเกษตร เพื่อสร้างความเข้มแข็งของภาคการเกษตรอย่างต่อเนื่อง\r\n\r\nในโอกาสอันเป็นมงคลนี้ มหาวิทยาลัยศรีปทุม   ขออาราธนาคุณพระศรีรัตนตรัย  และ  สิ่งศักดิ์สิทธิ์ทั้งหลายในสากลโลก   ได้โปรดดลบันดาลประทานพรให้ ผู้บริหาร และบุคลากรของสำนักงานพัฒนาการวิจัยการเกษตร​ (องค์การมหาชน)​ทุกท่าน   จงประสบความสุข  ความสำเร็จ  และความเจริญก้าวหน้าในสิ่งที่พึงปรารถนา  ทุกประการ'),
(87, 'ดร.', 'รัชนีพร พุคยาภรณ์ พุกกะมาน', 'อธิการบดี', 'มหาวิทยาลัยศรีปทุม', 'เนื่องในโอกาสครบรอบ 18  ปี   แห่งการสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)    วันจันทร์ที่  15  มีนาคม  2564    ในนามของคณะผู้บริหาร  บุคลากร  และนักศึกษามหาวิทยาลัยศรีปทุม ขอแสดงความยินดีและชื่นชมการขับเคลื่อนและนำพาองค์กรไปได้อย่างทันสมัยมีคุณภาพ  และมีประสิทธิผล ทั้งด้านการบริหาร การวิจัยการเกษตร เพื่อสร้างความเข้มแข็งของภาคการเกษตรอย่างต่อเนื่อง\r\n\r\nในโอกาสอันเป็นมงคลนี้ มหาวิทยาลัยศรีปทุม   ขออาราธนาคุณพระศรีรัตนตรัย  และ  สิ่งศักดิ์สิทธิ์ทั้งหลายในสากลโลก   ได้โปรดดลบันดาลประทานพรให้ ผู้บริหาร และบุคลากรของสำนักงานพัฒนาการวิจัยการเกษตร​ (องค์การมหาชน)​ทุกท่าน   จงประสบความสุข  ความสำเร็จ  และความเจริญก้าวหน้าในสิ่งที่พึงปรารถนา  ทุกประการ'),
(88, 'นาย', 'นายกัณภพ นิธิศธานี', 'เจ้าหน้าที่สนับสนุน', 'ARDA', 'ขอให้เจ้าหน้าที่และ Staff ทุกคนมีสุขภาพแข็งแรง มีความเจริญก้าวหน้าในหน้าที่การงาน และประสบความสำเร็จทุกประการ'),
(89, 'ผู้ช่วยศาสตราจารย์', 'ชุตินันท์  ประสิทธิ์ภูริปรีชา', 'อธิการบดีมหาวิทยาลัยอุบลราชธานี ', 'มหาวิทยาลัยอุบลราชธานี', 'มหาวิทยาลัยอุบลราชธานี ขอร่วมแสดงความยินดี เนื่องในโอกาส วันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร(องค์การมหาชน) ครบรอบ 18 ปี ขออาราธนาคุณพระศรีรัตนตรัยและสิ่งศักดิ์สิทธิ์ทั้งหลายในสากลโลก ได้โปรดดลบันดาลให้ท่านและคณะผู้บริหาร รวมทั้งบุคลากรบุคลากร  เจริญด้วยจตุรพิธพรชัยสัมฤทธิผลในสิ่งอันพึงปรารถนาทุกประการ เทอญ '),
(90, 'นาย', 'ประพิศ  จันทร์มา', 'อธิบดีกรมชลประทาน', 'กรมชลประทาน  กระทรวงเกษตรและสหกรณ์', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี'),
(91, 'รองศาสตราจารย์ นายสัตวแพทย์ ดร.', 'คณิศักดิ์  อรวีระกุล', 'คณบดีสำนักวิชาทรัพยากรการเกษตร', 'สำนักวิชาทรัพยากรการเกษตร จุฬาลงกรณ์มหาวิทยาลัย', 'ขอแสดงความยินดีกับสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ในวาระครบรอบ 18 ปี \r\nและขอให้เจริญรุ่งเรืองสืบไป\r\n'),
(92, 'นางสาว', 'เบญจพร ชาครานนท์', 'อธิบดีกรมพัฒนาที่ดิน', 'กรมพัฒนาที่ดิน', 'ขอแสดงความยินดีเนื่องในโอกาสวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี  '),
(93, 'นาย', 'อภิรักษ์  สงรักษ์', 'รองอธิการบดี', 'มหาวิทยาลัยเทคโนโลยีราชมงคลศรีวิชัย', 'ขอแสดงความยินดีในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน)  ขอเป็นกำลังใจต่อคณะผู้บริหาร และบุคลากร ที่ได้ผลักดันการวิจัยและพัฒนาการเกษตรของประเทศไทยสู่การแข่งขันได้หลากหลายมิติ อีกทั้งช่วยเพิ่มโอกาสและขีดความสามารถของนักวิจัย เกษตรกร ให้พร้อมรับการเปลี่ยนแปลงตามยุคสมัยใหม่  ส่งผลให้ประเทศไทยเป็นประเทศที่เป็นแหล่งผลิตอาหารคุณภาพได้อย่างยั่งยืน  '),
(94, 'นางสาว', 'ลักษณา เจริญใจ', 'ผศ.ดร.', 'วิทยาลัยเภสัชศาสตร์ ม.รังสิต', 'ขอแสดงความยินดีในโอกาสวันคล้ายวันสถาปนา สวก. ขอให้คงอยู่สนับสนุนงานวิจัยของประเทศไทยไปนานๆ'),
(95, 'นาย', 'จงรัก  วัชรินทร์รัตน์', 'อธิการบดีมหาวิทยาลัยเกษตรศาสตร์', 'มหาวิทยาลัยเกษตรศาสตร์', 'ในวาระอันเป็นมงคลยิ่งนี้ มหาวิทยาลัยเกษตรศาสตร์ขออาราธนาอำนาจคุณพระศรีรัตนตรัย และสิ่งศักดิ์สิทธิ์โปรดอำนวยพรให้ท่าน \r\nผู้บริหาร และบุคลากรของสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) จงประสบแต่ความสุขสวัสดิ์พิพัฒนมงคล \r\nสัมฤทธิผลเจริญด้วยจตุรพิธพรชัยทุกประการ\r\n'),
(96, 'นาย', 'บุญฤทธิ์ สินค้างาม', 'อาจารย์', 'คณะเกษตรศาสตร์ และทรัพยากรธรรมชาติ มหาวิทยาลัยพะเยา', 'ชื่นชมในนโยบายทุกด้านเพื่อการนำงานวิจัยทางด้านการเกษตรไปใช้ได้จริง และพัฒนาประเทศ'),
(97, 'นาย', 'ปริญญา น้อยดอนไพร', 'ผู้อำนวยการสำนักวิทยบริการและเทคโนโลยีสารสนเทศ', 'มหาวิทยาลัยราชภัฏสุราษฎร์ธานี', 'ขอแสดงความยินดีในโอกาสวันคล้ายวันสถาปนา'),
(98, 'ผู้ช่วยศาสตรจารย์ ', 'จิตนภา สมบูรณ์ศิลป์', 'หัวหน้าศูนย์วัฒนธรรม', 'มหาวิทยาลัยเทคโนโลยีราชมงคลอีสาน นครราชสีมา', 'ขอแสดงความยินดีในวันสถาปนา มีความร่มเย็นเป็นสุข เป็นกำลังสำคัญและทำงานเพื่อประเทศชาติต่อไป'),
(99, 'นางสาว', 'เพ็ญนภา ศรีวาปี', 'รักษาการในตำแหน่งผู้เชี่ยวชาญด้านแผนกลยุทธ์', 'กรมตรวจบัญชีสหกรณ์', 'ขออวยพรและแสดงความยินดีในโอกาสวันคล้ายวันสถาปนา สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) 15 มีนาคม 2564 ซึ่งได้สร้างงานที่เป็นประโยชน์แก่กิจการเกษตร ที่เป็นภาคส่วนที่สำคัญของประเทศ'),
(100, 'นาย', 'ภควัต ลำจวน', 'วิศวกรโยธาชำนาญการ', 'กรมชลประทาน', 'ขออำนาจคุณพระพุทธอวยพรให้บุคลากรสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ทุกท่านประสบแต่สิ่งดี สุขภาพพลานามัยสมบูรณ์แข็งแรง และคอยสนับสนุนเป็นหน่วยงานพัฒนาซึ่งสนับสนุนทุนวิจัยทางด้านการเกษตรเพื่อพัฒนาประเทศชาติสิบไป'),
(101, 'นางสาว', 'สุวรีย์ ยอดฉิม', 'รองอธิการบดีฝ่ายวิจัยและพัฒนา', 'มหาวิทยาลัยราชภัฏสวนสุนันทา', 'ข้าพเจ้า ผู้ช่วยศาสตราจารย์ ดร.สุวรีย์ ยอดฉิม รองอธิการบดีฝ่ายวิจัยและพัฒนา มหาวิทยาลัยราชภัฏสวนสุนันทา ขอแสดงความยินดีอย่างยิ่ง เนื่องในวันคล้ายวันสถาปนาสำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) ครบรอบ 18 ปี ทั้งนี้ข้าพเจ้าขอให้ทุกท่านประสบแต่ความสุข ความเจริญ และประสบความสำเร็จยิ่งๆขึ้นไป'),
(102, 'นาย', 'ธนพัฒน์ คำขาว', 'ผู้ประสานงานจากเอกชน', 'หน่วยงานเอกชน', 'ขอให้หน่วยเจริญรุ่งเรือง มีงานวิจัยที่เกิดประโยชน์ต่อสาธารณชนต่อไปเรื่่อยๆ'),
(103, 'นาย', 'test lasname', 'engineer', 'myhome', 'test');
