INSERT INTO `new_arda` (`id`, `name`, `detail`, `datein`, `pstatus`, `news_url`) VALUES
(288, 'สวก. ร่วมจัดนิทรรศการงาน ASEANbeauty Show 2018', '<p class=\"indent\">\r\n	สำนักงานพัฒนาการวิจัยการเกษตร (องค์การมหาชน) หรือ สวก. เข้าร่วมจัดแสดงผลงานวิจัยและนวัตกรรมผลิตภัณฑ์ด้านความงามและสุขภาพ ในงานเจรจาธุรกิจด้านความงามและสุขภาพ ASEANbeauty&amp;ASEANhealth and wellness 2018 ซึ่งจัดโดย บริษัท ยูบีเอ็ม เอเชีย (ประเทศไทย) จำกัด สภาอุตสาหกรรมแห่งประเทศไทย (F.T.I.) และ สมาคมผู้ผลิตเครื่องสำอางไทย (TCMA) ตั้งแต่วันที่ 3-5 พฤษภาคม 2561 ณ ฮอลล์ 103 และ 104 ณ ศูนย์นิทรรศการและการประชุมไบเทค บางนา กรุงเทพ ภายในงาน มีกิจกรรมต่างๆ ได้แก่ การสัมมนาทางวิชาการ การนำเสนอผลงานวิจัยและนวัตกรรมเกี่ยวกับเครื่องสำอาง และการแสดงสินค้าด้านสุขภาพและความงามของผู้ประกอบการกว่า 350 บริษัท จาก 20 ประเทศ เพื่อเปิดโอกาสให้ผู้ประกอบการอุตสาหกรรมเครื่องสำอางละผลิตภัณฑ์เสริมสุขภาพของไทยได้นำเทคโนโลยีมาพัฒนาต่อยอดสินค้าให้เกิดความแตกต่างและสร้างความโดดเด่น ตลอดจนสร้างเสริมความแข็งแกร่งให้กับอุตสาหกรรมสุขภาพและความงามให้กับประเทศไทยอีกด้วย จึงขอเชิญชวนผู้ที่สนใจเยี่ยมชมและร่วมกิจกรรมในงานดังกล่าว โดยสามารถดูรายละเอียดงานเพิ่มเติมได้ที่ <a href=\"http://www.aseanbeautyshow.com/\">http://www.aseanbeautyshow.com/</a></p>\r\n<p class=\"indent\">\r\n	<a href=\"/datas/file/1523354408.pdf\">รายละเอียด Click</a></p>\r\n<p class=\"indent\">\r\n	&nbsp;</p>\r\n<div class=\"con_img\">\r\n	<img alt=\"\" src=\"/datas/image/1523354223.jpg\" style=\"width: 931px; height: 1317px;\" /></div>\r\n', '2018-04-10', 1, ''),
